  'update',
  $payload${"moduleId":"nerve-conduction","revisionType":"quiz","title":"Evaluación: Velocidad de conducción sensitiva (VCS)","quizTopicId":"sensory-cv","passScore":70,"maxAttempts":null,"shuffleQuestions":true,"shuffleOptions":true,"questions":[{"id":"vcs-q1","sortOrder":0,"type":"single","difficulty":"basic","stem":"¿Cuál es la fórmula de la VCS en la lección, y qué latencia entra en ella?","options":[{"id":"vcs-q1-a","text":"Distancia dividida entre la latencia de inicio.","isCorrect":true},{"id":"vcs-q1-b","text":"Distancia dividida entre la latencia pico.","isCorrect":false},{"id":"vcs-q1-c","text":"Latencia pico menos latencia de inicio.","isCorrect":false},{"id":"vcs-q1-d","text":"Amplitud en µV dividida entre la distancia en cm.","isCorrect":false}],"explanation":"VCS = distancia / latencia de inicio. El pico no va en el denominador.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}]},{"id":"vcs-q2","sortOrder":1,"type":"single","difficulty":"intermediate","stem":"¿Qué velocidades sensitivas da la lección como normales en miembro superior y en miembro inferior?","options":[{"id":"vcs-q2-a","text":"Al menos 50 m/s en el superior y al menos 40 m/s en el inferior.","isCorrect":true},{"id":"vcs-q2-b","text":"Al menos 70 m/s en ambos, sin diferencia por extremidad.","isCorrect":false},{"id":"vcs-q2-c","text":"Al menos 40 m/s en la mano y 50 m/s en el pie.","isCorrect":false},{"id":"vcs-q2-d","text":"La sensitiva siempre es más lenta que la motora del mismo nervio.","isCorrect":false}],"explanation":"Esos son los umbrales de la lección. Añade que la VCS normal suele ser un poco más rápida que la velocidad motora del mismo nervio.\n\n📚 Referencia: Chen S, Andary M, Buschbacher R, et al.. Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations. Muscle & Nerve (2016). https://doi.org/10.1002/mus.25203","citations":[{"authors":"Chen S, Andary M, Buschbacher R, et al.","title":"Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations","journal":"Muscle & Nerve","year":2016,"url":"https://doi.org/10.1002/mus.25203"}]},{"id":"vcs-q3","sortOrder":2,"type":"image_choice","difficulty":"advanced","stem":"El trazo, a 1 ms/div, despega cerca de 2.5 ms. La distancia es 140 mm y el pico está en 3.2 ms. La motora del mismo nervio conduce a 52 m/s. ¿Cuál es la VCS?","options":[{"id":"vcs-q3-a","text":"56 m/s. Es normal para el miembro superior y, como espera la lección, algo más rápida que la motora.","isCorrect":true},{"id":"vcs-q3-b","text":"44 m/s, usando el pico, y por eso es más lenta que la motora.","isCorrect":false},{"id":"vcs-q3-c","text":"28 m/s, porque se suman inicio y pico.","isCorrect":false},{"id":"vcs-q3-d","text":"52 m/s, porque la sensitiva se copia de la motora.","isCorrect":false}],"explanation":"140 / 2.5 = 56 m/s, por encima de 50. Usar 3.2 ms daría 44 m/s y rompería la regla del inicio.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}],"imageUrl":"/quiz-traces/sensory-cv-vcs-q3.svg","imageAlt":"SNAP con inicio cerca de 2.5 ms y amplitud cercana a 22 µV, a 1 ms/div y 10 µV/div, sin el cálculo de velocidad escrito en la imagen."},{"id":"vcs-q4","sortOrder":3,"type":"single","difficulty":"intermediate","stem":"Un sural con inicio a 4.0 ms en 14 cm da 35 m/s. ¿Cómo lo clasifica el umbral de la lección para el miembro inferior?","options":[{"id":"vcs-q4-a","text":"Lento: el inferior se considera normal desde 40 m/s.","isCorrect":true},{"id":"vcs-q4-b","text":"Normal, porque 35 m/s supera el umbral de la mano.","isCorrect":false},{"id":"vcs-q4-c","text":"Normal para el pie, cuyo límite es 30 m/s.","isCorrect":false},{"id":"vcs-q4-d","text":"No calculable: el sural no tiene velocidad.","isCorrect":false}],"explanation":"140 mm / 4.0 ms = 35 m/s, por debajo de 40 m/s. El umbral de 50 m/s es el del miembro superior.\n\n📚 Referencia: Chen S, Andary M, Buschbacher R, et al.. Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations. Muscle & Nerve (2016). https://doi.org/10.1002/mus.25203","citations":[{"authors":"Chen S, Andary M, Buschbacher R, et al.","title":"Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations","journal":"Muscle & Nerve","year":2016,"url":"https://doi.org/10.1002/mus.25203"}]}],"examQuestions":[{"module_id":"nerve-conduction","topic_id":"sensory-cv","topic_name":"Velocidad de conducción sensitiva (VCS)","island_name":"EMG","stem":"Sural a 14 cm. Latencia de inicio 3.2 ms, latencia pico 4.0 ms. Motora del tibial en la pierna: 42 m/s. Piden la velocidad sensitiva.","difficulty":2,"is_critical":false,"findings":[{"type":"LAT","label":"Sural, inicio y pico","value":"3.2 ms y 4.0 ms a 140 mm"},{"type":"VCN","label":"Velocidad motora tibial","value":"42 m/s"}],"options":[{"text":"44 m/s con el inicio (140/3.2). Normal para el pie y ligeramente por encima de la motora.","is_correct":true,"feedback":"Supera 40 m/s. El pico daría 35 m/s y no es la fórmula."},{"text":"35 m/s, usando el pico, e informar desmielinización.","is_correct":false,"feedback":"35 m/s sale de dividir entre el pico."},{"text":"42 m/s, copiando la motora.","is_correct":false,"feedback":"La sensitiva se mide, no se hereda."},{"text":"50 m/s, porque ese es el mínimo del pie.","is_correct":false,"feedback":"50 m/s es el suelo del miembro superior; el inferior es 40 m/s."}],"pearl":"VCS = mm / ms de inicio. Mano ≥50 m/s, pie ≥40 m/s, y suele ir algo más rápida que la motora.","source_reference":"Chen S, Andary M, Buschbacher R, et al.. Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations. Muscle & Nerve (2016). https://doi.org/10.1002/mus.25203","tags":["nerve-conduction","sensory-cv"],"status":"DRAFT"}]}$payload$::jsonb,
